'use client';
import {useState} from 'react';
import {AtlasLauncher} from '@/features/admin/atlas/AtlasCharacter';
import CompanionCharacter from '@/features/central/assistant/CompanionCharacter';
export default function QA(){const [open,setOpen]=useState(false);const [pose,setPose]=useState('idle');return <main style={{minHeight:'100vh',background:'#10111e',color:'#eee2f5',padding:32}}><h1>Atlas · Comprobación local</h1><p>Escenario aislado, sin datos de clientes.</p><div style={{display:'grid',gridTemplateColumns:'repeat(auto-fit,minmax(200px,1fr))',gap:24,marginTop:40}}>{['Reservas','Mi turno','Notificaciones'].map(name=><section key={name} style={{padding:24,border:'1px solid #ad87cb55',borderRadius:20,background:'#21192e'}}><h2>{name}</h2><p>Vista de prueba</p><button>Revisar</button></section>)}</div><label>Campo de prueba <input aria-label="Campo de prueba"/></label><div style={{width:160,height:174,marginTop:40}}><CompanionCharacter pet="atlas" state="idle" gesture={pose}/></div>{['idle','walking','thinking','greeting','celebrating','sleeping'].map(x=><button key={x} onClick={()=>setPose(x)}>{x}</button>)}<AtlasLauncher workerId="atlas-local-qa" onOpen={()=>setOpen(true)}/>{open&&<section role="dialog" aria-label="Atlas abierto" style={{position:'fixed',right:20,top:30,padding:30,background:'#302040',zIndex:200}}><h2>Atlas</h2><button onClick={()=>setOpen(false)}>Cerrar</button></section>}</main>}
